-- 조건 메서드를 만든다

private BooleanExpression usernameStarts(String prefix) {
    return prefix == null ? null : member.username.startsWith(prefix);
}

private BooleanExpression ageGoe(Integer age) {
    return age == null ? null : member.age.goe(age);
}

private BooleanExpression ageLoe(Integer age) {
    return age == null ? null : member.age.loe(age);
}

private BooleanExpression teamNameEq(String name) {
    return name == null ? null : member.team.name.eq(name);
}

--   4.3절의 조건에 null 검사만 붙였다


-- 하나로 부른다

private List<Member> search(String prefix, Integer min,
                            Integer max, String teamName) {
    return queryFactory.selectFrom(member)
            .where(usernameStarts(prefix),
                   ageGoe(min),
                   ageLoe(max),
                   teamNameEq(teamName))
            .fetch();
}

