-- 문장 모양을 센다

@Test
void 문장_수() {
    Set<String> shapes = new LinkedHashSet<>();
    String[] prefixes = {null, "m"};
    Integer[] mins = {null, 15};
    Integer[] maxs = {null, 35};
    String[] teams = {null, "teamB"};
    for (String p : prefixes) for (Integer mi : mins)
      for (Integer ma : maxs) for (String t : teams) {
        em.clear();
        shapes.add(sqlCapture.capture(() -> search(p, mi, ma, t)));
    }
    System.out.println("서로 다른 문장: " + shapes.size());
}

