-- 조건을 합쳐 두면

private BooleanExpression ageBetween(Integer min, Integer max) {
    return ageGoe(min).and(ageLoe(max));
}

@Test
void 합치기() {
    try {
        queryFactory.selectFrom(member).where(ageBetween(null, 35)).fetch();
    } catch (Exception e) {
        System.out.println("예외: " + e.getClass().getSimpleName());
    }
}

